  assert.ok(text.includes('10% discount'), 'Should show discount percentage');
  // Line total: 5 * 8500 = 42500, Discount: 4250
  assert.ok(text.includes('€4,250.00') || text.includes('€4250.00'), 'Should show discount amount');
});

test('renderInvoiceText shows decimal discount', () => {
