test('renderInvoiceText shows total discount summary', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'STICKER', qty: 100, discountPercent: 5 }
    ]
  });

  const text = renderInvoiceText(r.value);

  // Total discount: 4250 + 250 = 4500
  assert.ok(text.includes('Discount:'), 'Should show discount summary line');
  assert.ok(text.includes('€45.00') || text.includes('€4,500.00'), 'Should show total discount amount');
});

test('renderInvoiceText does not show discount summary when no discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }
    ]
